<?php
require __DIR__.'/../../app/bootstrap.php';require_once __DIR__.'/../../app/api_v2.php';$u=api_v2_user('profile');$uid=(int)$u['user_id'];if($_SERVER['REQUEST_METHOD']==='POST'){$in=api_input();if(api_v2_device_id($in)==='')api_v2_error('device_id required',422);api_v2_register_device($uid,$in,api_v2_app_type($in));api_v2_event($uid,'device.sync',$in);api_v2_ok(['saved'=>true],$uid);}try{$q=db()->prepare('SELECT id,device_id,app_type,platform,device_name,os_version,app_version,build_number,locale,timezone,last_seen_at,status FROM mobile_app_devices WHERE user_id=? ORDER BY last_seen_at DESC');$q->execute([$uid]);api_v2_ok(['devices'=>$q->fetchAll()],$uid);}catch(Throwable $e){api_v2_ok(['devices'=>[]],$uid);}
